#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <string>
#include "../common/sha256.h"
static bool field(const std::string&j,const std::string&k,std::string&v){auto p=j.find("\""+k+"\"");if(p==std::string::npos)return false;p=j.find(':',p);if(p==std::string::npos)return false;p++;while(p<j.size()&&(j[p]==' '||j[p]=='\n'||j[p]=='\t'))p++;bool q=j[p]=='"';if(q)p++;auto e=q?j.find('"',p):j.find_first_of(",}\n",p);if(e==std::string::npos)return false;v=j.substr(p,e-p);return true;}
static bool hash(const std::string&p,std::string&h,uint64_t&z){char b[65];if(!nsha_file(p.c_str(),b,&z))return false;h=b;return true;}
int main(int ac,char**av){if(ac>=2&&std::string(av[1])=="create"){if(ac<4){std::cerr<<"usage: rom-manifest-cpp create IMAGE OUTPUT --title T --platform P --provenance TEXT\n";return 2;}std::string title,plat,prov,fmt="unknown",rights="unknown";bool red=false;for(int i=4;i<ac;i++){std::string a=av[i];if((a=="--title"||a=="--platform"||a=="--provenance"||a=="--format"||a=="--rights-status")&&i+1<ac){std::string v=av[++i];if(a=="--title")title=v;else if(a=="--platform")plat=v;else if(a=="--provenance")prov=v;else if(a=="--format")fmt=v;else rights=v;}else if(a=="--redistribution-allowed")red=true;else return 2;}if(title.empty()||plat.empty()||prov.empty())return 2;bool permitted=rights=="authorized"||rights=="redistribution_approved"||rights=="public_domain"||rights=="original_homebrew";if(red&&!permitted){std::cerr<<"error: redistribution_allowed conflicts with rights_status\n";return 2;}std::string h;uint64_t n;if(!hash(av[2],h,n)){std::perror(av[2]);return 2;}std::ofstream o(av[3]);if(!o)return 2;o<<"{\n \"schema_version\": 1,\n \"title\": \""<<title<<"\",\n \"platform\": \""<<plat<<"\",\n \"format\": \""<<fmt<<"\",\n \"size_bytes\": "<<n<<",\n \"sha256\": \""<<h<<"\",\n \"provenance\": \""<<prov<<"\",\n \"rights_status\": \""<<rights<<"\",\n \"redistribution_allowed\": "<<(red?"true":"false")<<"\n}\n";std::cout<<"manifest written; SHA-256 "<<h<<"\n";return o?0:2;}if(ac==4&&std::string(av[1])=="verify"){std::ifstream f(av[2]);if(!f)return 2;std::string j((std::istreambuf_iterator<char>(f)),{}),h,sz,actual;uint64_t n;if(!field(j,"sha256",h)||!field(j,"size_bytes",sz)){std::cout<<"FAIL: missing required field\n";return 1;}if(!hash(av[3],actual,n))return 2;if(std::stoull(sz)!=n){std::cout<<"FAIL: size mismatch\n";return 1;}if(h!=actual){std::cout<<"FAIL: sha256 mismatch\n";return 1;}std::cout<<"PASS: image matches manifest\n";return 0;}std::cerr<<"usage: rom-manifest-cpp create|verify ...\n";return 2;}
